function cpEsc(s){return String(s||'').replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]))}
function cpRenderNews(list){let box=document.getElementById('newsList');if(!box)return;let news=(list&&list.length?list:cpNewsProducts()).slice(0,3);box.innerHTML=news.map(x=>'<article class="newsItem">'+(x.immagine?'<img src="'+cpEsc(x.immagine)+'" alt="">':'')+'<div><b>'+cpEsc(x.nome)+'</b><span>'+cpEsc(x.categoria||'Novita')+'</span><strong>'+cpEsc(x.prezzo_str||cpPriceLabel(x.prezzo))+'</strong></div></article>').join('')}
function cpMergeExtras(prodotti){
  const removed=new Set(cpRemovedProducts());
  const collection=[...cpOfficialCollection(),...cpVerifiedCatalogReferences()].map(([nome,link,prezzo,immagine,disponibilita,novita=true])=>{
    const slug=cpKey({link});
    const id='HDN-WEB-'+slug;
    return {id,sku:slug,nome,link,prezzo,prezzo_str:cpPriceLabel(prezzo),immagine,disponibilita,categoria:cpCat(nome,''),novita};
  });
  const officialKeys=new Set(collection.map(cpKey));
  const merged=prodotti.filter(x=>!removed.has(cpKey(x))||officialKeys.has(cpKey(x)));
  const ids=new Set(merged.map(x=>x.id));
  const names=new Set(merged.map(x=>x.nome.toLowerCase()));
  for(const x of cpExtraProducts()){
    if((removed.has(cpKey(x))&&!officialKeys.has(cpKey(x)))||ids.has(x.id)||names.has(x.nome.toLowerCase()))continue;
    merged.push({...x,prezzo_str:x.prezzo_str||cpPriceLabel(x.prezzo)});
    ids.add(x.id);
    names.add(x.nome.toLowerCase());
  }
  const latestSlugs=[
    'liquid-polygel-super-lac-1-gel-costruttore-in-bottiglia',
    'liquid-polygel-super-lac-5-gel-costruttore-in-bottiglia'
  ];
  const newsKeys=new Set([...latestSlugs,...cpNewsProducts().map(cpKey)]);
  for(const x of merged)if(newsKeys.has(cpKey(x)))x.novita=true;
  const byKey=new Map();
  for(const item of merged){
    const key=cpKey(item);
    if(!byKey.has(key))byKey.set(key,[]);
    byKey.get(key).push(item);
  }
  for(const item of collection){
    const matches=byKey.get(cpKey(item));
    if(!matches){
      merged.push(item);
      continue;
    }
    for(const existing of matches){
      if(item.novita)existing.novita=true;
      existing.immagine=item.immagine;
      if(item.disponibilita!=='Da configurare'||matches.length===1){
        existing.disponibilita=item.disponibilita;
      }
    }
  }
  return merged;
}
async function cpLoadCatalogFromCsv(){
  let prodotti=[];
  try{
    const response=await fetch('HDNails_Catalogo_Facebook_Commerce.csv?v='+CATALOG_PATCH_VERSION,{cache:'no-store'});
    if(!response.ok)throw Error('Catalogo HTTP '+response.status);
    prodotti=cpCsvObjects(await response.text()).map(cpMapProduct).filter(x=>x.nome);
    if(!prodotti.length)throw Error('Catalogo vuoto');
  }catch(error){
    console.warn('Catalogo CSV non caricato',error);
    try{prodotti=JSON.parse(localStorage.hd_products_v53||localStorage.hd_products_v52||'[]')}catch{}
  }
  if(!prodotti.length){
    $('#status').textContent='Catalogo non disponibile. Controlla la connessione e ricarica.';
    return;
  }
  S.p=cpMergeExtras(prodotti).map(x=>({...x,categoria:normCat(x.categoria)})).sort(sortProducts);
  try{localStorage.hd_products_v53=JSON.stringify(S.p)}catch{}
  const productsByKey=new Map(S.p.map(x=>[cpKey(x),x]));
  const news=cpOfficialCollection().map(([,link])=>productsByKey.get(cpKey({link}))).filter(Boolean);
  cpRenderNews(news);
  ready();
  document.dispatchEvent(new Event('hd-catalog-ready'));
}

